1. `src/firebase.js` 파일에서 `initializeApp`, `getAuth`, `getFirestore`가 올바르게 임포트되었는지 확인합니다.
2. `firebaseConfig` 객체에 실제 Firebase 프로젝트의 구성 정보가 정확하게 포함되어 있는지 검증합니다.
3. `app`, `auth`, `db` 인스턴스를 모듈의 외부에서 접근할 수 있도록 `export` 문을 사용하여 내보냅니다.

```javascript
// src/firebase.js
import { initializeApp } from 'firebase/app';
import { getAuth } from 'firebase/auth';
import { getFirestore } from 'firebase/firestore';

const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "YOUR_AUTH_DOMAIN",
  projectId: "YOUR_PROJECT_ID",
  storageBucket: "YOUR_STORAGE_BUCKET",
  messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
  appId: "YOUR_APP_ID"
};

const app = initializeApp(firebaseConfig);
export const auth = getAuth(app);
export const db = getFirestore(app);
```

1. `src/components/Auth.js` 또는 별도의 파일에 `LoginForm` 및 `RegisterForm` 컴포넌트를 생성합니다.
2. 각 폼은 이메일과 비밀번호 입력을 위한 `<input type='email'>` 및 `<input type='password'>` 요소를 포함합니다.
3. 제출을 위한 버튼(`로그인`, `회원가입`)을 추가합니다.
4. Todo List 페이지 (`src/components/TodoList.js` 또는 `src/App.js`)에 현재 사용자 상태를 표시하고 로그아웃 기능을 트리거할 '로그아웃' 버튼을 추가합니다.
5. React hook (예: `useState`)을 사용하여 폼 입력 상태를 관리합니다.

```jsx
// src/components/Auth.js (예시)
import React, { useState } from 'react';

function AuthPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLogin, setIsLogin] = useState(true); // 로그인/회원가입 토글

  const handleSubmit = (event) => {
    event.preventDefault();
    // 이메일, 비밀번호를 사용하여 인증 로직 호출 (다음 태스크에서 구현)
    console.log(isLogin ? '로그인 시도' : '회원가입 시도', { email, password });
  };

  return (
    <div>
      <h2>{isLogin ? '로그인' : '회원가입'}</h2>
      <form onSubmit={handleSubmit}>
        <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="이메일" required />
        <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="비밀번호" required />
        <button type="submit">{isLogin ? '로그인' : '회원가입'}</button>
      </form>
      <button onClick={() => setIsLogin(!isLogin)}>
        {isLogin ? '계정이 없으신가요? 회원가입' : '이미 계정이 있으신가요? 로그인'}
      </button>
    </div>
  );
}
export default AuthPage;
```

1. `src/firebase.js`에서 내보낸 `auth` 객체를 사용하여 `createUserWithEmailAndPassword`, `signInWithEmailAndPassword`, `signOut` 함수를 호출하는 로직을 구현합니다.
2. 사용자 인증 상태를 관리하기 위한 React Context (예: `AuthContext`)를 생성하고, `onAuthStateChanged` 리스너를 사용하여 로그인 상태 변화를 감지하고 Context의 상태를 업데이트합니다.
3. `AuthContext`는 현재 로그인한 사용자 정보 (`user` 객체)와 로딩 상태 (`loading`)를 제공해야 합니다.
4. `AuthPage` 컴포넌트에서 로그인 및 회원가입 폼 제출 시 해당 인증 함수를 호출하고, 성공/실패 시 사용자에게 피드백을 제공합니다.
5. 로그아웃 버튼 클릭 시 `signOut` 함수를 호출합니다.

```jsx
// src/context/AuthContext.js (예시)
import React, { createContext, useContext, useEffect, useState } from 'react';
import { auth } from '../firebase'; // Task 1에서 내보낸 auth 인스턴스
import { createUserWithEmailAndPassword, signInWithEmailAndPassword, signOut } from 'firebase/auth';

const AuthContext = createContext(null);

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(firebaseUser => {
      setUser(firebaseUser);
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  const signup = (email, password) => createUserWithEmailAndPassword(auth, email, password);
  const login = (email, password) => signInWithEmailAndPassword(auth, email, password);
  const logout = () => signOut(auth);

  const value = { user, loading, signup, login, logout };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

// src/components/Auth.js (사용 예시)
// ... (이전 코드)
import { useAuth } from '../context/AuthContext';
// ...

function AuthPage() {
  // ... (state)
  const { signup, login } = useAuth();

  const handleSubmit = async (event) => {
    event.preventDefault();
    try {
      if (isLogin) {
        await login(email, password);
        console.log('로그인 성공');
      } else {
        await signup(email, password);
        console.log('회원가입 성공');
      }
    } catch (error) {
      console.error('인증 실패:', error.message);
      alert(error.message);
    }
  };
  // ...
}
// ...
```

1. `react-router-dom`을 사용하여 `BrowserRouter`를 설정합니다.
2. `/login` 경로에 `AuthPage` 컴포넌트를 연결하고, `/` 경로에 `TodoListPage` (아직 생성되지 않음) 컴포넌트를 연결합니다.
3. `useAuth` 훅을 활용하여 사용자 인증 상태를 확인하고, 로그인하지 않은 사용자에게는 `Navigate` 컴포넌트를 사용하여 `/login`으로 리디렉션하는 `ProtectedRoute` 컴포넌트를 구현합니다.
4. `App.js`에 `AuthProvider`를 감싸서 앱 전체에서 인증 상태에 접근할 수 있도록 합니다.

```jsx
// src/App.js
import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext'; // Task 3에서 구현
import AuthPage from './components/Auth'; // Task 2에서 구현
import TodoListPage from './components/TodoList'; // 다음 태스크에서 구현 예정

// 보호된 라우트 컴포넌트
const ProtectedRoute = ({ children }) => {
  const { user, loading } = useAuth();
  if (loading) {
    return <div>로딩 중...</div>; // 인증 상태 로딩 중 표시
  }
  return user ? children : <Navigate to="/login" replace />;
};

function App() {
  return (
    <Router>
      <AuthProvider>
        <Routes>
          <Route path="/login" element={<AuthPage />} />
          <Route 
            path="/" 
            element={
              <ProtectedRoute>
                <TodoListPage />
              </ProtectedRoute>
            }
          />
          {/* 다른 라우트들 */}
        </Routes>
      </AuthProvider>
    </Router>
  );
}
export default App;
```

1. **데이터 모델 정의:**
   - Collection: `todos`
   - Document (자동 생성 ID):
     - `text` (string): 할 일 내용
     - `completed` (boolean): 완료 여부
     - `createdAt` (timestamp): 생성 시간
     - `userId` (string): Todo를 생성한 사용자 ID (Firebase Auth의 `uid` 사용)

2. **Firestore 보안 규칙 작성:**
   Firebase 콘솔의 Firestore '규칙' 탭에서 다음 규칙을 적용합니다.
   - 모든 사용자는 `todos` 컬렉션의 문서에 접근할 수 없습니다.
   - 인증된 사용자만 `todos` 컬렉션에 접근할 수 있습니다.
   - 사용자는 자신의 `userId`와 일치하는 Todo 문서만 생성, 읽기, 수정, 삭제할 수 있습니다.

```firestore
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /todos/{todoId} {
      allow read, write: if request.auth != null && request.auth.uid == resource.data.userId;
      allow create: if request.auth != null && request.auth.uid == request.resource.data.userId;
    }
  }
}
```

1. `src/components/TodoList.js` 파일을 생성하고 `TodoListPage` 컴포넌트를 정의합니다.
2. 컴포넌트 내부에 새로운 Todo를 입력할 `<input type='text'>` 필드와 '추가' 버튼을 포함하는 폼을 구현합니다.
3. Todo 항목들을 표시할 `<ul>` 또는 `<div>` 기반의 리스트 구조를 만듭니다.
4. 각 Todo 항목은 텍스트, 완료 체크박스, 삭제 버튼을 위한 플레이스홀더를 포함해야 합니다.
5. Task 3에서 구현된 `useAuth` 훅을 사용하여 현재 로그인한 사용자 정보 (특히 `user.uid`)를 가져올 준비를 합니다.

```jsx
// src/components/TodoList.js (예시)
import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext'; // Task 3에서 구현

function TodoListPage() {
  const { user, logout } = useAuth();
  const [newTodoText, setNewTodoText] = useState('');
  const [todos, setTodos] = useState([]); // 임시 상태, 나중에 Firestore에서 가져옴

  const handleAddTodo = (event) => {
    event.preventDefault();
    if (newTodoText.trim() === '') return;
    console.log('새 Todo 추가 시도:', newTodoText);
    // Firestore 추가 로직 (다음 태스크에서 구현)
    setNewTodoText('');
  };

  return (
    <div>
      <h1>{user ? `${user.email}의 Todo List` : 'Todo List'}</h1>
      <button onClick={logout}>로그아웃</button>

      <form onSubmit={handleAddTodo}>
        <input
          type="text"
          value={newTodoText}
          onChange={(e) => setNewTodoText(e.target.value)}
          placeholder="새로운 할 일을 입력하세요"
        />
        <button type="submit">추가</button>
      </form>

      <h2>할 일 목록</h2>
      {todos.length === 0 ? (
        <p>할 일이 없습니다.</p>
      ) : (
        <ul>
          {todos.map(todo => (
            <li key={todo.id}>
              <input type="checkbox" checked={todo.completed} onChange={() => { /* 토글 로직 */ }} />
              <span>{todo.text}</span>
              <button onClick={() => { /* 삭제 로직 */ }}>삭제</button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
export default TodoListPage;
```

1. **조회 기능 (Read):**
   - `TodoListPage` 컴포넌트 내에서 `useEffect` 훅을 사용하여 컴포넌트 마운트 시 Firestore에서 Todo 목록을 가져옵니다.
   - `db` 인스턴스를 사용하여 `collection('todos')`를 참조하고, `where('userId', '==', user.uid)` 쿼리를 사용하여 현재 사용자의 Todo만 필터링합니다.
   - `orderBy('createdAt', 'asc')`를 사용하여 생성 시간 순으로 정렬합니다.
   - `onSnapshot` 리스너를 사용하여 실시간으로 데이터 변경사항을 감지하고 `setTodos`로 상태를 업데이트합니다.
   - `cleanup` 함수를 `useEffect`에서 반환하여 리스너를 해제합니다.

2. **생성 기능 (Create):**
   - `handleAddTodo` 함수 내에서 `addDoc` 함수를 사용하여 `todos` 컬렉션에 새 문서를 추가합니다.
   - 추가할 문서에는 `text` (입력 필드 값), `completed: false`, `createdAt: serverTimestamp()`, `userId: user.uid` 필드를 포함합니다.

```jsx
// src/components/TodoList.js (업데이트 예시)
import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { db } from '../firebase'; // Task 1에서 내보낸 db 인스턴스
import { collection, query, where, orderBy, onSnapshot, addDoc, serverTimestamp } from 'firebase/firestore';

function TodoListPage() {
  const { user, logout } = useAuth();
  const [newTodoText, setNewTodoText] = useState('');
  const [todos, setTodos] = useState([]);

  useEffect(() => {
    if (!user) return; // 사용자가 없으면 데이터를 가져오지 않음

    const q = query(
      collection(db, 'todos'),
      where('userId', '==', user.uid),
      orderBy('createdAt', 'asc')
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const todosData = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setTodos(todosData);
    });

    return () => unsubscribe(); // 클린업 함수
  }, [user]); // user 객체가 변경될 때마다 다시 실행

  const handleAddTodo = async (event) => {
    event.preventDefault();
    if (newTodoText.trim() === '' || !user) return;

    try {
      await addDoc(collection(db, 'todos'), {
        text: newTodoText.trim(),
        completed: false,
        createdAt: serverTimestamp(),
        userId: user.uid,
      });
      setNewTodoText('');
    } catch (error) {
      console.error('Todo 추가 실패:', error.message);
      alert('Todo 추가에 실패했습니다.');
    }
  };
  // ... (렌더링 부분은 Task 6과 동일)
}
```

1. `TodoListPage` 컴포넌트에서 각 Todo 항목 렌더링 시 `<input type='checkbox'>`에 `onChange` 이벤트 핸들러를 추가합니다.
2. 이벤트 핸들러 내에서 `updateDoc` 함수를 사용하여 해당 Todo 문서의 `completed` 필드를 현재 값의 반대로 업데이트합니다.
3. `doc(db, 'todos', todoId)`를 사용하여 특정 Todo 문서를 참조합니다.

```jsx
// src/components/TodoList.js (추가될 handleToggleCompleted 함수 및 사용 예시)
import { doc, updateDoc } from 'firebase/firestore'; // Firebase 임포트 추가
// ...

function TodoListPage() {
  // ... (기존 코드)

  const handleToggleCompleted = async (id, currentCompleted) => {
    try {
      const todoRef = doc(db, 'todos', id);
      await updateDoc(todoRef, {
        completed: !currentCompleted
      });
      console.log('Todo 완료 상태 토글 성공:', id);
    } catch (error) {
      console.error('Todo 완료 상태 토글 실패:', error.message);
      alert('Todo 상태 변경에 실패했습니다.');
    }
  };

  return (
    // ... (렌더링 부분)
    <ul>
      {todos.map(todo => (
        <li key={todo.id} style={{ textDecoration: todo.completed ? 'line-through' : 'none' }}>
          <input 
            type="checkbox" 
            checked={todo.completed} 
            onChange={() => handleToggleCompleted(todo.id, todo.completed)} 
          />
          <span>{todo.text}</span>
          {/* 삭제 버튼 등 */}
        </li>
      ))}
    </ul>
    // ...
  );
}
```

1. `TodoListPage` 컴포넌트에서 각 Todo 항목 렌더링 시 '삭제' 버튼에 `onClick` 이벤트 핸들러를 추가합니다.
2. 이벤트 핸들러 내에서 `deleteDoc` 함수를 사용하여 해당 Todo 문서를 Firestore에서 삭제합니다.
3. `doc(db, 'todos', todoId)`를 사용하여 특정 Todo 문서를 참조합니다.

```jsx
// src/components/TodoList.js (추가될 handleDeleteTodo 함수 및 사용 예시)
import { doc, deleteDoc } from 'firebase/firestore'; // Firebase 임포트 추가
// ...

function TodoListPage() {
  // ... (기존 코드)

  const handleDeleteTodo = async (id) => {
    if (!window.confirm('정말로 이 할 일을 삭제하시겠습니까?')) return;
    try {
      const todoRef = doc(db, 'todos', id);
      await deleteDoc(todoRef);
      console.log('Todo 삭제 성공:', id);
    } catch (error) {
      console.error('Todo 삭제 실패:', error.message);
      alert('Todo 삭제에 실패했습니다.');
    }
  };

  return (
    // ... (렌더링 부분)
    <ul>
      {todos.map(todo => (
        <li key={todo.id} style={{ textDecoration: todo.completed ? 'line-through' : 'none' }}>
          <input 
            type="checkbox" 
            checked={todo.completed} 
            onChange={() => handleToggleCompleted(todo.id, todo.completed)} 
          />
          <span>{todo.text}</span>
          <button onClick={() => handleDeleteTodo(todo.id)}>삭제</button>
        </li>
      ))}
    </ul>
    // ...
  );
}
```

1. 각 Todo 항목의 텍스트를 클릭하거나 별도의 '수정' 버튼을 통해 편집 모드로 전환하는 로직을 구현합니다.
2. 편집 모드에서는 텍스트가 `<input type='text'>` 필드로 변경되고, 사용자가 내용을 수정할 수 있도록 합니다.
3. 편집 모드를 종료(예: Enter 키 입력 또는 블러 이벤트)하면 `updateDoc` 함수를 사용하여 해당 Todo 문서의 `text` 필드를 새로운 값으로 업데이트합니다.

```jsx
// src/components/TodoList.js (추가될 handleUpdateText 함수 및 사용 예시)
import { doc, updateDoc } from 'firebase/firestore'; // Firebase 임포트 추가
// ...

function TodoListPage() {
  // ... (기존 코드)
  const [editingTodoId, setEditingTodoId] = useState(null);
  const [editingText, setEditingText] = useState('');

  const handleEditClick = (todo) => {
    setEditingTodoId(todo.id);
    setEditingText(todo.text);
  };

  const handleUpdateText = async (id) => {
    if (editingText.trim() === '') return;
    try {
      const todoRef = doc(db, 'todos', id);
      await updateDoc(todoRef, {
        text: editingText.trim()
      });
      setEditingTodoId(null); // 편집 모드 종료
      console.log('Todo 텍스트 수정 성공:', id);
    } catch (error) {
      console.error('Todo 텍스트 수정 실패:', error.message);
      alert('Todo 텍스트 수정에 실패했습니다.');
    }
  };

  return (
    // ... (렌더링 부분)
    <ul>
      {todos.map(todo => (
        <li key={todo.id} style={{ textDecoration: todo.completed ? 'line-through' : 'none' }}>
          <input 
            type="checkbox" 
            checked={todo.completed} 
            onChange={() => handleToggleCompleted(todo.id, todo.completed)} 
          />
          {
            editingTodoId === todo.id ? (
              <input
                type="text"
                value={editingText}
                onChange={(e) => setEditingText(e.target.value)}
                onBlur={() => handleUpdateText(todo.id)} // 블러 시 저장
                onKeyPress={(e) => { if (e.key === 'Enter') handleUpdateText(todo.id); }}
                autoFocus
              />
            ) : (
              <span onDoubleClick={() => handleEditClick(todo)}>{todo.text}</span>
            )
          }
          <button onClick={() => handleDeleteTodo(todo.id)}>삭제</button>
          {editingTodoId !== todo.id && <button onClick={() => handleEditClick(todo)}>수정</button>}
        </li>
      ))}
    </ul>
    // ...
  );
}
